from typing import List

class Solution:
    def findContentChildren(self, g: List[int], s: List[int]) -> int:
        used = [False] * len(s)

        def dfs(child: int) -> int:
            if child == len(g):
                return 0
            best = dfs(child + 1)
            for cookie in range(len(s)):
                if not used[cookie] and s[cookie] >= g[child]:
                    used[cookie] = True
                    best = max(best, 1 + dfs(child + 1))
                    used[cookie] = False
            return best

        return dfs(0)

