from typing import List

class Solution:
    def findContentChildren(self, g: List[int], s: List[int]) -> int:
        g.sort()
        s.sort()
        used = [False] * len(s)
        content = 0

        for greed in g:
            for i, size in enumerate(s):
                if not used[i] and size >= greed:
                    used[i] = True
                    content += 1
                    break
        return content

